// ---------------- Code: Config ----------------
let envUrl = '';
try { envUrl = $env.SUPABASE_URL || ''; } catch (e) { envUrl = ''; }
const cfg = {
  SUPABASE_URL: envUrl || "https://YOUR-PROJECT.supabase.co", // not secret; key lives in the Supabase credential
  SUPABASE_TABLE: "jev_signals",
  MIN_AGE_H: 2,            // only look at signals older than this (next 1h candle must be closed)
  SETTLE_MS: 120000,       // wait 2 min after candle close before scoring
  MAX_ROWS: 400,           // per run
  FLAT_THRESHOLD: 0.001    // |return| below 0.10% (about round-trip fees) = SCRATCH / SKIP_QUIET
};
cfg.PENDING_BEFORE = new Date(Date.now() - cfg.MIN_AGE_H * 3600e3).toISOString();
return [{ json: { config: cfg } }];

// Code: Plan — pick rows whose next full candle has closed
const cfg = $('Code: Config').first().json.config;
const IV = { '15m': 9e5, '30m': 18e5, '1h': 36e5, '2h': 72e5, '4h': 144e5, '1d': 864e5 };
const now = Date.now();
const rows = $input.all().flatMap(i => Array.isArray(i.json) ? i.json : (i.json && i.json.id != null ? [i.json] : []));
const out = [];
for (const r of rows) {
  const tf = IV[r.timeframe] ? r.timeframe : '1h';
  const iv = IV[tf];
  const created = Date.parse(r.created_at);
  if (!Number.isFinite(created) || !r.symbol) continue;
  const nextOpen = Math.floor(created / iv) * iv + iv; // first candle fully after the signal
  if (nextOpen + iv + cfg.SETTLE_MS > now) continue;   // not closed yet
  out.push({ json: { id: r.id, symbol: String(r.symbol).toUpperCase(), decision: r.decision || '', interval: tf, startTime: nextOpen, ageH: (now - created) / 36e5 } });
}
return out.slice(0, cfg.MAX_ROWS);

// Code: Score — label each signal from the candle that followed it
const cfg = $('Code: Config').first().json.config;
const plans = $('Code: Plan').all();
const resp = $input.all();
const thr = cfg.FLAT_THRESHOLD; // fraction, ~round-trip fees
const nowIso = new Date().toISOString();
const out = [];
plans.forEach((p, i) => {
  const plan = p.json;
  let k = null;
  try {
    const raw = resp[i] && resp[i].json ? (resp[i].json.data ?? resp[i].json) : null;
    const arr = typeof raw === 'string' ? JSON.parse(raw) : raw;
    if (Array.isArray(arr) && Array.isArray(arr[0]) && Number(arr[0][0]) === plan.startTime) k = arr[0];
  } catch (e) { k = null; }
  if (!k) {
    // no candle (delisted / symbol not on futures / API error): retry until 48h, then give up
    if (plan.ageH > 48) out.push({ json: { id: plan.id, patch: { outcome: 'NO_DATA', calibrated_at: nowIso } } });
    return;
  }
  const open = Number(k[1]), close = Number(k[4]);
  if (!(open > 0) || !Number.isFinite(close)) return;
  const ret = (close - open) / open;
  const d = plan.decision.toUpperCase();
  let outcome;
  if (d === 'LONG' || d === 'SHORT') {
    const s = d === 'LONG' ? ret : -ret;
    outcome = s > thr ? 'WIN' : s < -thr ? 'LOSS' : 'SCRATCH';
  } else {
    outcome = ret > thr ? 'SKIP_UP' : ret < -thr ? 'SKIP_DOWN' : 'SKIP_QUIET';
  }
  out.push({ json: { id: plan.id, patch: { next_candle_return: Math.round(ret * 1e6) / 1e6, outcome, calibrated_at: nowIso } } });
});
return out;

// ---------------- Code: Summary ----------------
const scored = $('Code: Score').all();
const counts = {};
for (const s of scored) { const o = s.json.patch.outcome; counts[o] = (counts[o] || 0) + 1; }
const failed = $input.all().filter(i => i.json && i.json.error).length;
return [{ json: { planned: $('Code: Plan').all().length, scored: scored.length, patch_errors: failed, counts } }];
